/* Live quiz states must override the captured, static button appearance. */
.source-funnel .source-control[data-action="next"] {
  background-color: var(--source-tone-6);
  border-color: var(--source-tone-7);
  color: var(--source-tone-5);
}
.source-funnel .source-control[data-action="next"] :is(div, p, span, svg, path) {
  background-color: var(--source-tone-1);
  color: inherit;
}
.source-funnel .source-control[data-action="next"]:hover {
  background-color: var(--source-tone-7);
}
.source-funnel .source-control[data-action="toggle"] .clone-216 {
  display: grid;
  place-items: center;
  padding: 0;
  flex: 0 0 26px;
}
.source-funnel .source-control[data-action="toggle"] .clone-217 {
  position: static;
  opacity: 0;
}
.source-funnel .source-control[data-action="toggle"][aria-pressed="true"] .clone-216 {
  background-color: var(--source-tone-6);
  border-color: var(--source-tone-6);
}
.source-funnel .source-control[data-action="toggle"][aria-pressed="true"] :is(.clone-217, .clone-217 path) {
  opacity: 1;
  color: var(--source-tone-5);
}
/* Let the guarantee grow when its two lines wrap, instead of clipping them. */
.source-funnel[data-step="27"] :is(.clone-1036, .clone-1037, .clone-1038, .clone-1039, .clone-1040, .clone-1042, .clone-1043) {
  height: auto;
  min-height: 0;
}
.source-funnel[data-step="27"] .clone-1039 { min-height: 92px; }
.source-funnel[data-step="27"] :is(.clone-1040, .clone-1042) { min-width: 0; }
.source-funnel[data-step="27"] .clone-1042 { flex: 1; width: auto; }
.source-funnel[data-step="27"] :is(.clone-1043, .clone-1044, .clone-1046) {
